CREATE OR REPLACE FUNCTION public.get_plan_address(_plan uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.plans; result text; BEGIN SELECT * INTO p FROM public.plans WHERE id=_plan; IF auth.uid() IS NULL OR p.id IS NULL THEN RETURN NULL; END IF; IF p.host_id IS DISTINCT FROM auth.uid() AND (NOT public.org_access(p.organisation_id,auth.uid()) OR NOT public.is_plan_member(_plan,auth.uid()) OR now()<p.starts_at-interval '2 hours') THEN RETURN NULL; END IF; SELECT address INTO result FROM public.plan_addresses WHERE plan_id=_plan; RETURN result; END $$;